    for base, dirs, fs in os.walk(os.path.join(SERVICES, svc)):
        for f in fs:
            out.append(os.path.join(base,f))
    return sorted(out)

def is_pointer(path):
    try:
        with open(path, "rb") as fh:
            first = fh.readline()
    except OSError:
        return False
    return first.decode("utf-8","replace").rstrip("\r\n") == POINTER

def py_files(svc):
    return [p for p in files(svc) if p.endswith(".py") and os.sep+"src"+os.sep in p]

def read(path):
    with open(path, encoding="utf-8") as fh: return fh.read()

def dockerfile_froms(text):
    out=[]
    for line in text.splitlines():
        s=line.strip()
        if not s or s.startswith("#"): continue
        parts=s.split()
        if parts[0].upper()=="FROM":
            toks=[t for t in parts[1:] if not t.startswith("--")]
            out.append((line, toks[0] if toks else ""))
    return out

def dockerfile_users(text):
    out=[]
    for line in text.splitlines():
        s=line.strip()
        if not s or s.startswith("#"): continue
        parts=s.split()
        if parts[0].upper()=="USER":
            out.append((line, parts[1] if len(parts)>1 else ""))
    return out

def codeowners_rules(text):
    rules=[]
    for line in text.splitlines():
        s=line.strip()
        if not s or s.startswith("#"): continue
        parts=s.split()
        if len(parts)>=2:
            rules.append((parts[0], parts[1:]))
    return rules

def audit(svc):
