    if ptr:
        res["status"]="unverifiable"
        res["_ev"]["pointers"]=[os.path.relpath(p,ROOT) for p in ptr]
        return res
    try:
        cfg=json.loads(read(os.path.join(svc_dir,"config.json")))
    except Exception as e:
        res["_ev"]["config_error"]=repr(e); cfg={}
    V=[]
    ev=res["_ev"]
    public = cfg.get("exposure")=="public"
    # C1
    if public:
        t=cfg.get("timeout_s")
        ok=isinstance(t,(int,float)) and not isinstance(t,bool) and t<=30
        ev["C1"]={"public":True,"timeout_s":t,"ok":ok}
        if not ok: V.append("C1")
    # C2
    hp=os.path.join(svc_dir,"src","handlers.py")
    tree=None
    if os.path.exists(hp):
        try: tree=ast.parse(read(hp))
        except Exception as e: ev["parse_error"]=repr(e)
    if tree is not None:
        missing=[]
        for n in ast.walk(tree):
            if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith("handle_"):
