    svc_dir=os.path.join(SERVICES,svc)
    allf=files(svc)
    ptr=[p for p in allf if is_pointer(p)]
    res={"service":svc,"status":"compliant","violations":[],"_ev":{}}
    if ptr:
        res["status"]="unverifiable"
        res["_ev"]["pointers"]=[os.path.relpath(p,ROOT) for p in ptr]
        return res
    try:
        cfg=json.loads(read(os.path.join(svc_dir,"config.json")))
    except Exception as e:
        res["_ev"]["config_error"]=repr(e); cfg={}
    V=[]
    ev=res["_ev"]
    public = cfg.get("exposure")=="public"
    # C1
    if public:
        t=cfg.get("timeout_s")
        ok=isinstance(t,(int,float)) and not isinstance(t,bool) and t<=30
        ev["C1"]={"public":True,"timeout_s":t,"ok":ok}
        if not ok: V.append("C1")
    # C2
    hp=os.path.join(svc_dir,"src","handlers.py")
    tree=None
    if os.path.exists(hp):
        try: tree=ast.parse(read(hp))
        except Exception as e: ev["parse_error"]=repr(e)
    if tree is not None:
        missing=[]
        for n in ast.walk(tree):
            if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith("handle_"):
                if ast.get_docstring(n,clean=False) is None:
                    missing.append((n.name,n.lineno))
        ev["C2"]={"missing_docstrings":missing}
        if missing: V.append("C2")
    # C3 / C9 over src py
    prints=[]; secrets=[]; parse_errs=[]
    for p in py_files(svc):
        try: t=ast.parse(read(p))
        except Exception as e:
            parse_errs.append((os.path.relpath(p,ROOT),repr(e))); continue
        for n in ast.walk(t):
            if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=="print":
                prints.append((os.path.relpath(p,ROOT),n.lineno))
            if isinstance(n,ast.Constant) and isinstance(n.value,str):
                if n.value.startswith(("sk_live_","AKIA")):
                    secrets.append((os.path.relpath(p,ROOT),n.lineno,n.value[:24]))
            if isinstance(n,ast.JoinedStr):
                # report literal segments that start with prefix
                for v in n.values:
                    if isinstance(v,ast.Constant) and isinstance(v.value,str) and v.value.startswith(("sk_live_","AKIA")):
                        secrets.append((os.path.relpath(p,ROOT),n.lineno,"fstring:"+v.value[:24]))
    ev["C3"]={"calls":prints}; ev["C9"]={"literals":secrets}
    if parse_errs: ev["parse_errors"]=parse_errs
    if prints: V.append("C3")
    # C4
    r=cfg.get("retries"); ok=isinstance(r,int) and not isinstance(r,bool) and 1<=r<=5
    ev["C4"]={"retries":r,"ok":ok}
    if not ok: V.append("C4")
    # C5
    dfp=os.path.join(svc_dir,"Dockerfile")
    if os.path.exists(dfp):
        froms=dockerfile_froms(read(dfp))
        bad=[]
        for line,ref in froms:
            m=re.search(r"@sha256:[0-9a-f]{64}$",ref)
            if not m: bad.append((line,ref,len(ref.split("@")[-1]) if "@" in ref else None))
        ev["C5"]={"froms":[(l,r) for l,r in froms],"bad":bad}
