    # C6
    if os.path.exists(dfp):
        users=dockerfile_users(read(dfp))
        if not users:
            ev["C6"]={"users":[],"ok":False}; V.append("C6")
        else:
            line,u=users[-1]; name=u.split(":")[0]
            ok=name not in ("root","0")
            ev["C6"]={"users":users,"last":u,"ok":ok}
            if not ok: V.append("C6")
    else:
        ev["C6"]="no dockerfile"; V.append("C6")
    # C7
    rp=os.path.join(svc_dir,"README.md")
    ok=os.path.exists(rp) and any(line=="## Runbook" for line in read(rp).splitlines())
    ev["C7"]={"ok":ok}
    if not ok: V.append("C7")
    # C8
    cp=os.path.join(svc_dir,"CODEOWNERS")
    team=cfg.get("team")
    rules=codeowners_rules(read(cp)) if os.path.exists(cp) else []
    star=[r for r in rules if r[0]=="*"]
    ok=any(owners==["@team-"+str(team)] for _,owners in star)
    ev["C8"]={"team":team,"star_owners":[o for _,o in star],"ok":ok}
    if not ok: V.append("C8")
    # C9 append already
    if secrets and "C9" not in V: V.append("C9")
    # C10
    hc=cfg.get("healthcheck")
    defined=set()
    if tree is not None:
        defined={n.name for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
    ok=False; want=None
    if isinstance(hc,str) and hc:
        seg=hc.rstrip("/").split("/")[-1]
        want="handle_"+seg
        ok=want in defined
    ev["C10"]={"healthcheck":hc,"want":want,"defined_matches":sorted(defined & {want} if want else set()),"ok":ok}
    if not ok: V.append("C10")
    # C11
    ok=cfg.get("metrics_port")!=cfg.get("port")
    ev["C11"]={"port":cfg.get("port"),"metrics_port":cfg.get("metrics_port"),"ok":ok}
    if not ok: V.append("C11")
    # C12
    reqp=os.path.join(svc_dir,"requirements.txt")
    bad=[]
    if os.path.exists(reqp):
        for i,line in enumerate(read(reqp).splitlines(),1):
            s=line.strip()
            if not s or s.startswith("#"): continue
            # allow inline comment
            core=s.split(" #",1)[0].strip()
            if not re.match(r"^[A-Za-z0-9][A-Za-z0-9._-]*(\[[^\]]+\])?==[^\s;]+$",core):
                bad.append((i,line))
    else:
        bad.append((0,"<missing requirements.txt>"))
    ev["C12"]={"bad":bad}; 
    if bad: V.append("C12")
    # C13
    ok=cfg.get("log_level")!="DEBUG"
    ev["C13"]={"log_level":cfg.get("log_level"),"ok":ok}
    if not ok: V.append("C13")
    # C14
    if public:
        mb=cfg.get("max_body_kb")
        ok=isinstance(mb,(int,float)) and not isinstance(mb,bool) and mb<=1024
        ev["C14"]={"max_body_kb":mb,"ok":ok}
        if not ok: V.append("C14")
    # C15
    tp=os.path.join(svc_dir,"tests")
    names=os.listdir(tp) if os.path.isdir(tp) else []
    matches=[n for n in names if n.startswith("test_") and n.endswith(".py") and os.path.isfile(os.path.join(tp,n))]
    ev["C15"]={"tests":names,"matches":matches,"ok":bool(matches)}
    if not matches: V.append("C15")
    order=[f"C{i}" for i in range(1,16)]
    res["violations"]=sorted(set(V),key=order.index)
    res["status"]="violations" if res["violations"] else "compliant"
    return res

